--
-- Table structure for table `Ai_chat_session`
--

DROP TABLE IF EXISTS `Ai_chat_session`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Ai_chat_session` (
  `session_id` int NOT NULL AUTO_INCREMENT,
  `pacient_id` int DEFAULT NULL,
  `doctor_id` int DEFAULT NULL,
  `naslov` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `kontekst_json` mediumtext COLLATE utf8mb4_unicode_ci,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`session_id`),
  KEY `idx_ai_chat_pacient` (`pacient_id`,`updated_at`),
  KEY `idx_ai_chat_doctor` (`doctor_id`,`updated_at`),
  CONSTRAINT `fk_ai_chat_doctor` FOREIGN KEY (`doctor_id`) REFERENCES `Doctors` (`doctor_ID`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_ai_chat_pacient` FOREIGN KEY (`pacient_id`) REFERENCES `patient` (`patient_ID`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=104 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `Ai_chat_session`
