INSERT INTO `Aparati` VALUES (1,'Рентгенографија','Дијагностичка метода со рентгенски зраци за визуелизација на коскени и органски структури со цел откривање на паталошки промени','rentgen',1,'2026-02-10 20:41:21'),(2,'Ехо томографија','Ултразвучен преглед на органи и меки ткива во реално време за дијагностика на различни заболувања','eho_tomografija',1,'2026-02-10 20:41:21'),(3,'Ехокардиографија','Ултразвучен преглед на срцето и неговата функција за проценка на кардиоваскуларни состојби','ehokardiografija',1,'2026-02-10 20:41:21'),(4,'Периметар','Испитување на видното поле за проценка на периферниот вид и откривање на визуелни дефекти','perimetar',1,'2026-02-10 20:41:21'),(5,'ЕХО на УГС и простата','Ултразвучен преглед на урогениталниот систем и простатата за дијагностика на урогенитални заболувања','eho_ugs_prostata',1,'2026-02-10 20:41:21'),(6,'Компјутерска томографија','Дијагностичка метода со рентгенски зраци за детални сликовни прикази на органи и ткива во тридимензионален приказ','kt',1,'2026-02-10 20:41:21'),(7,'Гастроскопија','Ендоскопски преглед на горниот дел од дигестивниот систем (стомак и дванаесетпалечно црево) за дијагностика и третман','gastroskopija',1,'2026-02-10 20:41:21'),(8,'Доплер на артериски или венски крвни садови на екстремитети','Ултразвучен преглед со доплер техника за проценка на протокот на крв во артериите и вените на екстремитетите','dopler_ekstremiteti',1,'2026-02-10 20:41:21'),(9,'Колоноскопија','Ендоскопски преглед на дебелото црево за дијагностика на колоректални заболувања и полипи','kolonoskopija',1,'2026-02-10 20:41:21'),(10,'Магнетна резонанца','Дијагностичка метода со магнетни полиња за детални сликовни прикази на меки ткива, мозок, зглобови и органи','mri',1,'2026-02-10 20:41:21'),(11,'Дензитометрија','Метода за мерење на густината на коските за дијагностика на остеопороза и проценка на ризикот од фрактури','denzitometrija',1,'2026-02-10 20:41:21'),(12,'Оптичка кохерентна томографија заден сегмент (ОЦТ)','Неинвазивна дијагностичка метода за детална визуелизација на задниот сегмент на окото (ретина, макула, оптички нерв)','oct_zaden_segment',1,'2026-02-10 20:41:21'),(13,'Дермоскоп','Дијагностички инструмент за зголемен приказ на кожата за проценка на дерматолошки лезии и малигни промени','dermoskop',1,'2026-02-10 20:41:21');
/*!40000 ALTER TABLE `Aparati` ENABLE KEYS */;
