INSERT INTO `Novosti` VALUES (1,'Извештај за извршени здравствени услуги до 1 декември 2025','линичка болница Штип е клучна алка во здравствениот систем и носител на најголемиот товар во Источниот регион. И покрај ограничениот број на вработени, само 415 посветени професионалци, нашиот колектив секојдневно обезбедува квалитетна, навремена и достапна здравствена услуга.\r\nВо периодот од 1 јануари до 1 декември 2025 година се реализирани, да напоменеме дека ова е информација само за дел од службите:\r\n10977 уролошки амбулантски прегледи, 402 приеми на одделение, 193 операции, 67 биопсии на простата.\r\nАнестезиолошкиот тим сработи 2272 операции и 1200 консултации\r\n458 728 лабораториски анализи, 72 383 повеќе за разлика од целата 2024та година\r\n1380 коронарографии, 498 стентирања, 69 периферии, ехокардиографии 2349, 9210 кардиолошки прегледи, 122 коронарни стрес теста\r\n5551 инфектолошки преглед, 493 приеми\r\n8088 невролошки прегледи 613 хоспитализации\r\nУво нос грло има извршено 6926 прегледи, 52 приеми 11 операции и 66 интервенции\r\n21633 ортопедски прегледи, 595 хоспитализации 504 операции, 580 мали интервенции\r\n1283 максилофацијални прегледи, 80 интервеницц, 103 приеми ( еден лекар специјалист)\r\n6471 хируршки прегледи, 1005 приеми, 731 операција, 788 интервенции\r\n2477 прегледи на физикална терапија и 323 приеми\r\n5593 психијатриски прегледи и 113 приеми\r\n16583 рентген графии, 9439 компјутерски томографии, 2065 магнетни резонанци, 5960 еха, 380 мамографии ( во моментот не е во функција, во процес на сервисирање)\r\nОд еден онколог се направени 1967 онколошки прегледи\r\n10466 дерматовенеролошки прегледи и 180 хоспитализации\r\n5189 педијатриски прегледи, 653 приеми\r\n4249 гинеколошки прегледи, 1165 приеми, 437 породувања 229 операции 488 интервенции\r\n11884 офталмолошки прегледи, 568 офталмолошки операции \r\nОвие бројки не се муабети, ова се факти кои зборуваат за обемот на работа, одговорноста и посветеноста на нашиот тим.\r\nСвесни сме дека условите не се идеални, но секој ден даваме се од себе да обезбедиме поефикасна и поквалитетна услуга. Веруваме дека само заедно, персоналот, институциите и граѓаните можеме да ја унапредуваме здравствената грижа и да ја направиме подобра за сите.\r\nКлиничка болница Штип е една од поважните алки во секундарното здравство во Македонија\r\nВи благодариме за довербата.\r\nПродолжуваме силно – со вас, за вашето здравје.\r\nКлиничка болница Штип','https://kbstipstorage.blob.core.windows.net/kbstiptcontaine/slika 1.jpg',46,'2026-03-10 13:23:15','2026-03-16 16:44:41',NULL,NULL,NULL,NULL),(2,'Oктомври и Ноември – Месеци на подигнување на свеста за ракот кај мажи и жени','Како и минатата година, така и оваа, Клиничка болница Штип го дава својот придонес со своите капацитети во месеците посветени на здравјето – „Розов октомври“, месец на женското здравје, и ноември, месец на машкото здравје.\r\n👉 Во соработка и со идеен поттик од  Ротари клубот и Lions клубот, КБ Штип на своите сограѓани им овозможува бесплатни превентивни прегледи.\r\nВо консултација со началниците на Урологија @Blagoja Zdravev , Рентгенологија Sevda Gacova  и Клиничка лабораторија Velice Nikolova , ќе бидат овозможени одреден број бесплатни прегледи секоја сабота во месец ноември.\r\n🌿 Треба да напоменеме дека за перфектна целина, освен идеја , потребни се соработка и капацитети.\r\nЦелта на здравствениот систем не е само да лекува, туку и да едуцира, да превенира и да поттикнува здрави навики – за поздрава, посреќна и посилна заедница! 💪\r\nОбезбедени се 60 бесплатни скрининг прегледи(ехо и пса) за карцином на простата и 30 бесплатни ехо прегледи на дојка. \r\n🙏 Настанот е поддржан од Pharmanova,Imako Vino  Winery, EAM Т-Shirt, V&E, Rotary Club Stip и Lions Club Stip, Клиничка Болница Штип\r\nГолема благодарност до СОМА ( Студентски организирана медицинска асоцијација )','https://kbstipstorage.blob.core.windows.net/kbstiptcontaine/slika 2.jpg',46,'2026-03-10 13:58:39','2026-03-16 16:45:49',NULL,'[\"uploads/novosti/670759d206d04fc2b1cc4fea2e5c6bdc.jpg\", \"uploads/novosti/71246d0f260a47b2bd0c03c70ee8c613.jpg\"]',NULL,NULL),(3,'ЗАКАЖУВАЊЕ ВАКЦИНАЦИЈА ВО ДОМАШНИ УСЛОВИ','Министерството за здравство информира дека превентивни тимови од здравствени установи започнаа со вакцинација против сезонски грип во домашни услови, на стари и неподвижни лица, како и на лица со попреченост.\r\n\r\nИсто така, превентивните тимови ги посетуваат домовите за стари лица каде се врши имунизација против сезонски грип.\r\n\r\nБрој за пријавување во Клиничка Болница Штип: 078-537-005.\r\nВакцинацијата ќе се одвива во Здравствен дом \"Панче Караѓозов\"- Штип.\r\nАдреса: Христијан Карпош 1','https://kbstipstorage.blob.core.windows.net/kbstiptcontaine/slika3.jpg',46,'2026-03-10 14:22:52','2026-03-16 16:46:37',NULL,NULL,NULL,NULL),(4,'Проф. д-р Владо Поповски оперира во КБ Штип','Угледниот максилофацијален хирург, проф. д-р Владо Поповски оперира во КБ Штип\r\nПроф, д-р Владо Поповски, угледен специјалист по максилофацијална хирургија е ангажиран за периодична работа во КБ Штип. Поповски врши прегледи и изведува сложени операции на штипското одделение најмалку три пати месечно.','https://kbstipstorage.blob.core.windows.net/kbstiptcontaine/slika 4.jpg',46,'2026-03-10 14:36:10','2026-03-16 16:47:15','https://www.youtube.com/watch?v=NR38rPG-PbQ',NULL,'28','260'),(6,'Клиничка Болница Штип: 23 нови вработени','<p>Клиничка Болница Штип доби согласност од Министерството за финансии за вработување на 23 нови лица.</p><p>Меѓу нив се стоматолог, фармацевт, радиолошки техничар, физиотерапевти, медицински сестри и акушерки, како и болничари, хигиеничари и возач.</p><p>Во наредната недела се очекува согласност за вработување на уште две лица на позицијата информатичари.</p><p>Ова вработување ќе ги задоволи сите потреби на болницата и ќе обезбеди подобри услови за пациентите.</p>','https://img.youtube.com/vi/29lVeKZZtiQ/hqdefault.jpg',46,'2026-05-14 14:15:15','2026-05-14 14:15:15','https://www.youtube-nocookie.com/embed/29lVeKZZtiQ',NULL,NULL,NULL),(13,'Клиничка Болница Штип најавува нови вработувања','<p>Клиничка Болница Штип најавува кадровско зајакнување со нови вработувања на околу 60 лица до крајот на годината.</p><p>Болницата веќе добила согласност за продолжување на договорите на определено време, а во тек е постапка за вработување на неопределено за 25 работни позиции.</p><p>Фокусот ќе биде ставен на средниот и техничкиот персонал, кадар со кој болницата во моментот најмногу кубури, како што се болничари, сестри, шофери, економисти и правници.</p><p>Буџетот на Клиничката болница се планира да се зголеми за 10 до 15%, што ќе овозможи набавка и сервисирање на медицинска опрема, како и реконструкција на потпорниот ѕид.</p>','https://img.youtube.com/vi/7euRBt7V92s/hqdefault.jpg',46,'2026-05-19 18:01:16','2026-05-19 18:01:16','https://www.youtube-nocookie.com/embed/7euRBt7V92s',NULL,NULL,NULL),(18,'Ургентниот центар во КБ Штип ќе започне со работа од септември','<p>Ургентниот центар во Клиничка Болница Штип ќе започне со работа од септември, изјави заменик генералниот директор доктор Билјана Евтимова. Центарот ќе биде хируршки и интернистички и ќе обслужува пациенти од источниот и југоисточниот регион.</p><p>Пациентите ќе можат да бидат дијагностицирани и третирани во центарот, а ако е потребно, ќе бидат упуќани во други одделенија во болницата за да бидат третирани.</p><p>Во моментов, болницата има недостиг од суплементот контраст кој се користи за длабинско рентгенско снимање. Пациентите кои треба да прават снимки со контраст се молат да се воздржат од тоа во наредните две недели, додека не се решат проблемите со производителот.</p><p>Исто така, е објавен оглас за прием на 25 нови работници, што треба да го ублажи дефицитот од кадар во болницата. Плановите се да се објави уште еден оглас за прием на околу 30 вработувања, во септември или октомври.</p>','https://img.youtube.com/vi/9fXwrTTBfec/hqdefault.jpg',46,'2026-05-27 21:12:30','2026-05-27 21:12:30','https://www.youtube-nocookie.com/embed/9fXwrTTBfec',NULL,NULL,NULL),(19,'Терапија за МС во КБ Штип','<p>Денес, на Светскиот ден за борба против мултиплекс склероза, е констатиран пораст на бројот на лица со оваа болест.</p><p>Фондот за здравствено осигурување најави дека терапијата за МС ќе биде подостапна, бидејќи ќе се дистрибуира во повеќе центри во државата, меѓу кои и во Клиничка болница Штип.</p><p>Експертите потенцираат дека пристапот кон оваа болест е изменет, особено со новите терапии за жените кои сакаат да се остварат како мајки.</p><p>Новите препораки за третман на пациентите со мултиплекс склероза и бременост овозможуваат употреба на одредени лекови во тек на бременоста, а кај високоефикасна терапија, препораките се дека има промени во однос на периодот на ефективна контрацепција пред концепцијата.</p>','https://img.youtube.com/vi/otWO4GrK2n0/hqdefault.jpg',46,'2026-05-28 11:09:48','2026-05-28 11:09:48','https://www.youtube-nocookie.com/embed/otWO4GrK2n0',NULL,NULL,NULL),(20,'Елон Муск во Roadster','<p>Елон Муск е познат по своите иновативни идеи и производи, а една од неговите омилени активности е возење со својот електричен автомобил Roadster.</p><p>Во една прилика, тој изјавил дека ова возило е совршено за возење во место како Калифорнија, каде што времето е сончево и убаво. Според него, електричниот автомобил му овозможува да чуе звуците на природата и да ужива во возењето.</p><p>Муск исто така зборува за својата друга компанија, SpaceX, која користи ракетно гориво за своите летала. Тој вели дека не е апсолутно против употребата на гориво, но сака да создаде подобра иднина во која ќе можеме да уживаме во нешта што ни се допаѓаат, без да го уништуваме светот.</p><p>На крај, тој предлага убава рута за возење со Roadster, која е долж брегот на Калифорнија, кон Санта Барбара, непосредно пред зајдисонце.</p>','https://img.youtube.com/vi/VSNXhHTLLIk/hqdefault.jpg',46,'2026-05-28 11:17:55','2026-05-28 11:17:55','https://www.youtube-nocookie.com/embed/VSNXhHTLLIk',NULL,NULL,NULL);
